class Solution {
    public int getMaximumGenerated(int n){
        if(n==0)return 0;
        int[] nums=new int[n+1];
        nums[1]=1;
        int answer=1;
        for(int i=2;i<=n;i++){
            nums[i]=i%2==0?nums[i/2]:nums[i/2]+nums[i/2+1];
            answer=Math.max(answer,nums[i]);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun getMaximumGenerated(n:Int):Int{
        if(n==0)return 0;
        val nums=IntArray(n+1);
        nums[1]=1;
        var answer=1;
        for(i in 2..n){
            nums[i]=if(i%2==0)nums[i/2] else nums[i/2]+nums[i/2+1];
            answer=maxOf(answer,nums[i])
        };
        return answer
    }
}

code.cpp:
class Solution {
    public: int getMaximumGenerated(int n){
        if(!n)return 0;
        vector<int> nums(n+1);
        nums[1]=1;
        int answer=1;
        for(int i=2;i<=n;++i){
            nums[i]=i%2==0?nums[i/2]:nums[i/2]+nums[i/2+1];
            answer=max(answer,nums[i]);
        }
        return answer;
    }
};
